fn boot() ? {
    backoff :: [Int].{1, 2, 4, 8}
    tls :: TlsConfig.{min: .Tls13, alpn: ["h2", "http/1.1"]}
    auth :: .Password.{username: "mailer", password: secret()}
    server :: Server.{name: "edge", tls: tls, auth: auth}
    serve(server, .{port: 8080, on: true}, backoff)
    if server.status() == .Listening -> print("up")
    // constructions parse inside headers today — no parens needed:
    if tls == TlsConfig.{min: .Tls13, alpn: ["h2"]} { print("strict") }
}

fn boot() ? {
    backoff :: [Int]{1, 2, 4, 8}
    tls :: TlsConfig{min: .Tls13, alpn: ["h2", "http/1.1"]}
    auth :: .Password{username: "mailer", password: secret()}
    server :: Server{name: "edge", tls: tls, auth: auth}
    serve(server, {port: 8080, on: true}, backoff)
    if server.status() == .Listening -> print("up")
    // header positions need parens now (the Rust/Go rule):
    if tls == (TlsConfig{min: .Tls13, alpn: ["h2"]}) { print("strict") }
