    a_low :: a & U64{4294967295}
    a_high :: a >> 32
    b_low :: b & U64{4294967295}
    b_high :: b >> 32
    p0 :: a_low * b_low
    p1 :: a_high * b_low
    p2 :: a_low * b_high
    p3 :: a_high * b_high
    middle :: (p0 >> 32) + (p1 & U64{4294967295}) + (p2 & U64{4294967295})
    return Product128{low: (p0 & U64{4294967295}) | ((middle & U64{4294967295}) << 32), high: p3 + (p1 >> 32) + (p2 >> 32) + (middle >> 32)}
}

use core.mem
#Target(Arch.x86_64)
#[Unsafe("audited x86-64 mul"), FFI(asm)]
fn wide_mul_x86(a: U64, b: U64) Product128 -> {
    """
    ; inout a -> return.low: rax
    ; in b: reg
    ; out high -> return.high: rdx
    ; options nomem, nostack
    ; unwind forbid
    mul {b}
    """
}
