    @if @build.target.arch == { "x86_64" -> wide_mul_x86(a, b) else -> portable_wide_mul(a, b) }
}
fn run() {
    #Unsafe("call the selected target implementation") {
        result :: wide_mul(3, 7)
        print(result)
    }
}
