// Complex: the same protocol reader
use core.encoding.json as json
#Codable
struct Request { id: Int, method: String }

fn show_id(text: String) {
    msg :: json.parse(text) ?? return
    print(json.integer(&msg.field("id") ?? return) ?? -1)
}

fn run() {
    show_id("{\"id\": 7}")                       // 7
    show_id("{\"id\": 7.0}")                     // -1, with no reason
    show_id("{\"id\": 1e999999}")                // -1
    show_id("{\"id\": 92233720368547758070}")    // -1: past i64
    json.decode<Request>("{\"id\": 1e999999, \"method\": \"ping\"}") ? r -> print(r.id) ! errors -> print(errors)
    // still running after two minutes: decode<Int> builds a million-digit number
}

